contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 loanID_) public payable {
        uint256 returned = c.newCollateralFor(loanID_); if (__ESBMC_reverted()) return;
        assert(returned == returned);
    }

    receive() external payable {}
}

