pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID_) internal {
        uint256 returned;
        try c.newCollateralFor(loanID_) returns (uint256 __r) { returned = __r; } catch { return; }
        assertTrue(returned == returned);
    }

    function testFuzz_run(uint256 loanID_) public {
        _run(loanID_);
    }

    receive() external payable {}
}
